let spacingBank=null,bankBusy=false;const bankResources=['metal','crystal','eonium'];
async function loadSpacingBank(){spacingBank=await centralDirectoryRequest('/api/spacing-bank');return spacingBank;}
function bankStatsHTML(b){return '<div class="alliance-kpis">'+bankResources.map(k=>'<div class="quick"><small>'+RES[k].label+' reserves</small><strong>'+nfmt(b.balances[k])+'</strong><span>Minimum '+nfmt(b.settings.minimum[k])+'</span></div>').join('')+'</div><p class="meta">Tax '+b.settings.tax+'% · Maximum exchange '+nfmt(b.settings.maxTrade)+' · Per-player tick limit '+nfmt(b.settings.tickLimit)+' · Total traded '+nfmt(b.volume)+'</p>';}
async function renderSpacingBank(){const root=document.getElementById('galaxyFundContent');if(!root||!state.centralPlayerId)return;try{const b=await loadSpacingBank();let module=root.querySelector('#spacingBankModule');if(!module){module=document.createElement('section');module.id='spacingBankModule';module.className='panel';root.append(module);}module.innerHTML='<div class="ph"><div class="pt">SPACING BANK COLLECTIVE</div><span class="meta">UNIVERSAL RESOURCE EXCHANGE · ROUND '+b.generation+'</span></div><div class="settings-body"><p>Exchange planetary resources with the common treasury. Reserves are finite; each new round starts with the configured fund.</p>'+bankStatsHTML(b)+'<div class="controls"><div class="field"><label>Offer</label><select id="bankFrom">'+bankResources.map(k=>'<option>'+k+'</option>').join('')+'</select></div><div class="field"><label>Receive</label><select id="bankTo">'+bankResources.map((k,i)=>'<option '+(i===1?'selected':'')+'>'+k+'</option>').join('')+'</select></div><div class="field"><label>Amount offered</label><input id="bankAmount" type="number" min="1" max="'+b.settings.maxTrade+'" value="1000"></div><button class="btn primary" data-bank-trade>CONFIRM EXCHANGE</button></div><p id="bankQuote" class="note"></p><p id="bankMessage" role="status"></p><h4>Personal exchange receipts</h4>'+b.history.filter(t=>t.action==='trade').map(t=>'<p>Tick '+t.tick+' · '+nfmt(t.amount)+' '+esc(t.from)+' → '+nfmt(t.receive)+' '+esc(t.to)+' · Tax '+nfmt(t.fee)+' '+esc(t.to)+'</p>').join('')+'</div>';updateBankQuote();}catch{}}
function updateBankQuote(){if(!spacingBank)return;const from=document.getElementById('bankFrom')?.value,to=document.getElementById('bankTo')?.value,amount=Number(document.getElementById('bankAmount')?.value),out=document.getElementById('bankQuote');if(!out)return;const gross=Math.floor(amount*spacingBank.settings.values[from]/spacingBank.settings.values[to]),fee=Math.floor(gross*spacingBank.settings.tax/100);out.textContent=from===to?'Choose two different resources.':'Receive '+nfmt(gross-fee)+' '+to+' · Fee '+nfmt(fee)+' '+to+' · Your '+from+' stock '+nfmt(state.resources[from]);}
async function tradeSpacingBank(){if(bankBusy)return;bankBusy=true;const b=spacingBank,from=document.getElementById('bankFrom').value,to=document.getElementById('bankTo').value,amount=Number(document.getElementById('bankAmount').value);try{if(typeof syncOwnedColony==='function')await syncOwnedColony(true);const fresh=await centralDirectoryRequest('/api/spacing-bank');if(fresh.revision!==b.revision||JSON.stringify(fresh.settings)!==JSON.stringify(b.settings))throw Error('The quote changed. Review the updated bank and confirm again.');const result=await centralDirectoryRequest('/api/spacing-bank',{action:'trade',id:crypto.randomUUID(),generation:b.generation,revision:b.revision,from,to,amount});await refreshSharedPlanets();addNews('Spacing Bank Collective exchange: '+amount+' '+from+' offered; '+result.trade.receive+' '+to+' received; tax '+result.trade.fee+' '+to+'.','good');update();await renderSpacingBank();notify('Exchange settled.');}catch(e){await renderSpacingBank();document.getElementById('bankMessage').textContent=e.message;}finally{bankBusy=false;}}
async function renderSpacingBankAdmin(){const root=document.getElementById('spacingBankAdmin');if(!root)return;try{const b=await loadSpacingBank();if(!b.canConfigure){root.textContent='Staff access required.';return;}root.innerHTML='<section class="panel"><div class="ph"><div class="pt">SPACING BANK COLLECTIVE · TREASURY CONTROL</div><span class="meta">CHANGES ARE LOGGED</span></div><div class="settings-body">'+bankStatsHTML(b)+'<p>Starting reserves apply on the next round. Exchange limits, values, minimums and tax apply after saving. Tax is retained as reduced output, not minted separately.</p><div class="admin-form">'+bankResources.map(k=>'<div class="field"><label>'+RES[k].label+' round start</label><input type="number" min="0" id="bankStarting-'+k+'" value="'+b.settings.starting[k]+'" '+(b.canSetStarting?'':'disabled')+'></div><div class="field"><label>'+RES[k].label+' minimum reserve</label><input type="number" min="0" id="bankMinimum-'+k+'" value="'+b.settings.minimum[k]+'"></div><div class="field"><label>'+RES[k].label+' exchange value</label><input type="number" min="0.1" max="100" step="0.1" id="bankValue-'+k+'" value="'+b.settings.values[k]+'"></div>').join('')+'<div class="field"><label>Exchange tax %</label><input type="number" min="0" max="25" id="bankTax" value="'+b.settings.tax+'"></div><div class="field"><label>Maximum transaction</label><input type="number" min="1" id="bankMax" value="'+b.settings.maxTrade+'"></div><div class="field"><label>Per-player, per-tick allowance</label><input type="number" min="1" id="bankTick" value="'+b.settings.tickLimit+'"></div></div><button class="btn primary" data-bank-configure>SAVE BANK POLICY</button><p id="bankAdminMessage"></p></div></section>';}catch(e){root.textContent=e.message;}}
async function configureSpacingBank(){const settings={starting:{},minimum:{},values:{},tax:Number(document.getElementById('bankTax').value),maxTrade:Number(document.getElementById('bankMax').value),tickLimit:Number(document.getElementById('bankTick').value)};for(const k of bankResources){settings.starting[k]=Number(document.getElementById('bankStarting-'+k).value);settings.minimum[k]=Number(document.getElementById('bankMinimum-'+k).value);settings.values[k]=Number(document.getElementById('bankValue-'+k).value);}try{await centralDirectoryRequest('/api/spacing-bank',{action:'configure',settings});await renderSpacingBankAdmin();document.getElementById('bankAdminMessage').textContent='Policy saved. Starting reserves apply next round.';}catch(e){document.getElementById('bankAdminMessage').textContent=e.message;}}
document.addEventListener('input',e=>{if(['bankFrom','bankTo','bankAmount'].includes(e.target.id))updateBankQuote();});document.addEventListener('click',e=>{if(e.target.closest('[data-bank-trade]'))tradeSpacingBank();if(e.target.closest('[data-bank-configure]'))configureSpacingBank();if(e.target.closest('[data-page="galaxyFund"]'))setTimeout(renderSpacingBank,100);});setTimeout(renderSpacingBank,3000);setInterval(()=>{if(document.getElementById('page-galaxyFund')?.classList.contains('active')&&!document.querySelector('#spacingBankModule input:focus,#spacingBankModule select:focus'))renderSpacingBank();},30000);
